  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'sha256=' + crypto.createHmac('sha256', secret)
    .update(timestamp + '.' + method + '.' + path + '.' + body).digest('hex');
  return {
    url: base.replace(/\/$/, '') + path,
