return $input.all().map(({ json }) => {
  const body = JSON.stringify({
    idempotencyKey: json.idempotencyKey,
    loanId: json.loanId,
    outcome: json.outcome,
    detail: json.detail,
  });
  return { json: signedRequest('POST', '/n8n/reminder-status', body) };
});
